import{DERBY_CONFIG as A}from"./config.min.js";export function trackAt(t,d=A){const u=d.track,s=u.slopeSine,c=u.slopeLength,n=u.transitionLength,o=s*(c+n/2);if(t<=c)return{sin:s,cos:Math.sqrt(1-s*s),curvature:0,height:o-s*t};if(t<c+n){const f=t-c,h=s*(1-f/n),x=Math.sqrt(1-h*h);return{sin:h,cos:x,curvature:s/n/x,height:o-s*c-s*(f-f*f/(2*n))}}return{sin:0,cos:1,curvature:0,height:0}}export function startHeight(t=A){return trackAt(0,t).height}export function sideRubOf(t,d=A){const u=d.physics.wobble;if(t.balance<0)return t.sideRub+u.extra+u.wheelie;if(t.balance>=u.safe)return t.sideRub;const s=(u.safe-t.balance)/u.safe;return t.sideRub+u.extra*s*s}export function runCar(t,d=null,{record:u=0}={},s=A){const c=s.physics,n=c.g,o=c.dt,f=s.track.courseLength,h=t.mass,x=h+t.rotatingMass,l=d===null?0:s.laneDefects[d]||0,i=t.axleMu*t.axleRatio,r=sideRubOf(t,s),e=.5*c.airDensity*t.cdA,a=s.track.slopeLength,g=i+c.rollingResistance+l,F=(_,v)=>{const k=_-t.comX,R=trackAt(k,s),y=h*(n*R.cos+v*v*R.curvature),w=k>a?r:t.sideRub;return(h*n*R.sin-g*y-w-e*v*v)/x},b=u>0?[{t:0,s:0,v:0}]:null,N=u>0?Math.round(u/o):0;let m=0,p=0,L=0,M=0;const T=Math.round(c.maxSeconds/o);for(;M<T;){const _=F(m,p),v=p+_*o/2,k=F(m+p*o/2,v),R=m+v*o,y=p+k*o;if(M++,R>=f){const w=(f-m)/(R-m),S=L+o*w,D=p+(y-p)*w;return b&&b.push({t:S,s:f,v:D}),{time:S,speed:D,dnf:!1,samples:b}}if(y<=0&&M>1)return{time:c.maxSeconds,speed:0,dnf:!0,samples:b,stoppedAt:m};m=R,p=y,L=M*o,b&&M%N===0&&b.push({t:L,s:m,v:p})}return{time:c.maxSeconds,speed:p,dnf:!0,samples:b,stoppedAt:m}}export function shownTime(t){return Math.round(t*1e3)/1e3}export function runRace(t,d=A,{record:u=0}={}){const s=d.track.lanes,c=t.map(i=>{const r=[];for(let e=0;e<s;e++)r.push(runCar(i,e,{record:u},d));return r}),n=[];for(let i=0;i<s;i++)n.push(t.map((r,e)=>{const a=(e+i)%s,g=c[e][a];return{car:e,lane:a,time:shownTime(g.time),dnf:g.dnf}}));const o=t.map((i,r)=>{let e=0;for(const a of n)e+=a[r].time;return shownTime(e/n.length)}),f=t.map((i,r)=>{let e=0;for(let a=0;a<s;a++)e+=c[r][a].time;return e}),h=t.map((i,r)=>{let e=n[0][r];for(const a of n)a[r].time<e.time&&(e=a[r]);return e}),x=t.map((i,r)=>r).sort((i,r)=>o[i]-o[r]||f[i]-f[r]||i-r),l=[];for(let i=0;i<s;i++){let r=0,e=0;for(const a of n)for(const g of a)g.lane===i&&(r+=g.time,e++);l.push(e?shownTime(r/e):null)}return{heats:n,average:o,best:h,standings:x,laneAverage:l,runs:c}}export function neutralTime(t,d=A){return runCar(t,null,{},d).time}export function explain(t,{kitMass:d,blockCdA:u,bestCdA:s,idealBalance:c},n=A){const o=neutralTime(t,n),f=n.rules[t.rules]||n.rules.standard,h=n.physics.axleFriction.stock,x=h*n.physics.axleFriction.deburred*n.physics.axleFriction.polish.reduce((e,a)=>e*a,1)*n.physics.axleFriction.graphite,l=e=>neutralTime({...t,...e},n),i=e=>({balance:e,comX:t.rearAxle-e}),r=[{id:"weight",saved:l({mass:d})-o,more:o-l({mass:f.maxMass})},{id:"balance",saved:l(i((t.rearAxle-t.frontAxle)/2))-o,more:o-l(i(c))},{id:"axles",saved:l({axleMu:h})-o,more:o-l({axleMu:x})},{id:"alignment",saved:l({sideRub:n.physics.sideRub.misaligned})-o,more:o-l({sideRub:n.physics.sideRub.aligned})},{id:"shape",saved:l({cdA:u})-o,more:o-l({cdA:s})}];return{time:o,lines:r}}
